// ========================================
// CONFIGURATION - UPDATE THESE VALUES
// ========================================
const TODOIST_PROJECT_NAME = 'Work';  // <-- Your Todoist project name
const GOOGLE_SHEET_ID = 'your-google-sheet-id-here';  // <-- From the Sheet URL

// ========================================
// Compute yesterday's date info
// ========================================
const now = new Date();
const yesterday = new Date(now);
yesterday.setUTCDate(yesterday.getUTCDate() - 1);

const fullYear = yesterday.getUTCFullYear();
const shortYear = fullYear.toString().slice(2);
const month = (yesterday.getUTCMonth() + 1).toString().padStart(2, '0');
const day = yesterday.getUTCDate().toString().padStart(2, '0');

const monthNames = {
  '01': 'Jan', '02': 'Feb', '03': 'Mar', '04': 'Apr',
  '05': 'May', '06': 'Jun', '07': 'Jul', '08': 'Aug',
  '09': 'Sep', '10': 'Oct', '11': 'Nov', '12': 'Dec'
};

const isoDate = `${fullYear}-${month}-${day}`;
const tabName = `${monthNames[month]}-${shortYear}`;
const startIso = `${isoDate}T00:00:00Z`;
const endIso = `${isoDate}T23:59:59.999999Z`;

return [{
  json: {
    isoDate,
    tabName,
    startIso,
    endIso,
    projectName: TODOIST_PROJECT_NAME,
    sheetId: GOOGLE_SHEET_ID
  }
}];

const setup = $('Setup: Config & Dates').first().json;
const response = $input.first().json;
const projects = response.results || response;

const project = projects.find(p => p.name === setup.projectName);
if (!project) {
  throw new Error(`Project '${setup.projectName}' not found. Available: ${projects.map(p => p.name).join(', ')}`);
}

return [{
  json: {
    ...setup,
    projectId: project.id
  }
}];

const setup = $('Find Project ID').first().json;
const sheetData = $input.first().json;
const rows = sheetData.values || [];

// Find the row matching yesterday's date in column A
let rowIndex = -1;
for (let i = 0; i < rows.length; i++) {
  if (rows[i] && rows[i][0] === setup.isoDate) {
    rowIndex = i + 1; // 1-based for Sheets API
    break;
  }
}

if (rowIndex === -1) {
  throw new Error(`Date ${setup.isoDate} not found in tab '${setup.tabName}'`);
}

// Check if column E (index 4) already has data
const row = rows[rowIndex - 1];
const cellValue = (row && row.length >= 5) ? row[4] : '';
const cellEmpty = !cellValue || cellValue.trim() === '';

return [{
  json: {
    ...setup,
    rowIndex,
    cellEmpty,
    currentCellValue: cellValue || '',
    cellRef: `${setup.tabName}!E${rowIndex}`
  }
}];

const setup = $('Find Row & Check Cell').first().json;
const response = $input.first().json;
const tasks = response.items || [];

let taskString;
if (tasks.length === 0) {
  taskString = 'N/A';
} else {
  taskString = tasks.map(t => t.content || '').join('; ');
}

return [{
  json: {
    sheetId: setup.sheetId,
    cellRef: setup.cellRef,
    taskString,
    taskCount: tasks.length
  }
}];
